package com.nthexperience.desktop;

import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;

/** Regression of the owner's portrait screenshots, using actual layout, taps and popups. */
public final class ElevenScreenshotSmoke extends Instrumentation {
 MainActivity home;View root;DesktopStore store;int checks;
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{
  store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("desktop_labels",true).putInt("desktop_label_size",12).putInt("desktop_icon_percent",80).putInt("desktop_columns_portrait",5).putInt("desktop_rows_portrait",9).putString("ten_search_mode","Icon").commit();
  getTargetContext().getSharedPreferences(InitializationState.PREFS,0).edit().putInt("flow_version",2).putInt("step",7).commit();
  getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).commit();
  home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();
  ui(()->{try{JSONObject folders=store.folders();List<String> ids=new ArrayList<>();for(int n=0;n<21;n++){String id="folder:"+new UUID(12,n+1);ids.add(id);folders.put(id,new JSONObject().put("name","Folder "+(n+1)).put("items",new JSONArray().put("@notes")));}store.prefs.edit().putString("app_folders",folders.toString()).commit();store.desktop(ids);store.quickLaunch(Arrays.asList("@notes","@calendar"));home.applyTenAppearance();}catch(JSONException e){throw new RuntimeException(e);}});settle();
  for(boolean landscape:new boolean[]{false,true})for(String alignment:new String[]{"Left","Center"}){
   ui(()->{home.setRequestedOrientation(landscape?ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);store.prefs.edit().putString("eleven_taskbar_alignment",alignment).putBoolean("taskbar_expanded",true).commit();home.applyTenAppearance();home.open("@notes");});settle();
   ui(()->{View bar=find("Eleven taskbar"),start=find("Start menu"),search=find("Search"),peek=find("Show desktop");check(search!=null&&search.isShown(),"Portrait and landscape retain the magnifier");Rect sb=bounds(start),qb=bounds(search),pb=bounds(peek);check(sb.bottom<=bounds(bar).bottom&&qb.left>=sb.right,"Bottom Start and Search do not overlap");check(pb.width()>=Aero.dp(home,8)&&pb.right<=bounds(bar).right,"Show desktop stays at the right edge inside the safe taskbar");
    ElevenTaskbarItems items=TenSmoke.find(root,ElevenTaskbarItems.class);View running=null;for(int i=0;i<items.getChildCount();i++)if(ElevenTaskbarItems.running(items.getChildAt(i))){running=items.getChildAt(i);break;}check(running!=null&&bounds(running).bottom<=sb.top,"Open apps occupy the upper row");if(alignment.equals("Left"))check(bounds(running).left==sb.left,"Left upper apps align with Start at the left edge");
   });
   if(!landscape&&alignment.equals("Left")){ui(()->{DesktopIconGrid grid=TenSmoke.find(root,DesktopIconGrid.class);for(int i=0;i<grid.getChildCount();i++){LinearLayout tile=(LinearLayout)grid.getChildAt(i);TextView label=(TextView)tile.getChildAt(1);Rect visible=new Rect();check(label.getGlobalVisibleRect(visible)&&visible.height()==label.getHeight(),"Every initial 5 by 9 desktop label is visible");check(visible.bottom<=bounds(find("Eleven taskbar")).top,"Bottom row clears expanded taskbar without scrolling");}});shot("eleven-screenshot-desktop");}
   tap(find("Show desktop"));settle();ui(()->check(TenSmoke.find(root,DesktopWindow.class).getVisibility()!=View.VISIBLE,"Show desktop tap minimizes the actual window"));
   tap(find("Restore desktop windows"));settle();ui(()->check(TenSmoke.find(root,DesktopWindow.class).getVisibility()==View.VISIBLE,"Second desktop tap restores the same window"));
   ui(()->TenSmoke.find(root,DesktopWindow.class).closeWindow());settle();
   View search=find("Search");tap(search);settle();ui(()->{StartMenu menu=TenSmoke.find(root,StartMenu.class);check(menu.getVisibility()==View.VISIBLE&&menu.searchMode,"Magnifier opens Search");check(findWithin(menu,"Suggested")!=null,"Search shows suggestions");check(find("Start profile and power").getVisibility()==View.GONE,"Search uses its own result surface");menu.search.setText("Calculator");});settle();ui(()->{StartMenu menu=TenSmoke.find(root,StartMenu.class);check(findWithin(menu.appList,"Calculator")!=null,"Search finds the actual calculator");check(findWithin(menu.appList,"Search the web")!=null,"Explicit web search remains available");});if(!landscape&&alignment.equals("Left"))shot("eleven-screenshot-search");
   ui(()->{home.onBackPressed();home.open("start-menu:");store.prefs.edit().putString("eleven_start_folders","Settings,Documents,Downloads,Music,Pictures,Videos").putBoolean("eleven_start_hide_profile",false).commit();TenSmoke.find(root,StartMenu.class).refreshName();});settle();
   ui(()->{StartMenu menu=TenSmoke.find(root,StartMenu.class);View footer=find("Start profile and power"),power=findWithin(footer,"Power");check(bounds(footer).left==bounds(menu).left&&bounds(footer).right==bounds(menu).right,"Start footer spans the panel edge to edge");check(bounds(power).right<=bounds(menu).right&&bounds(power).width()==Aero.dp(home,44),"Power stays visible beside all folder shortcuts");power.performClick();});settle();
   ui(()->{StartMenu menu=TenSmoke.find(root,StartMenu.class);DesktopContextMenu popup=(DesktopContextMenu)field(menu,"footerMenu");check(popup.showing(),"Power opens a native popover");View content=(View)field(popup,"items");check(bounds(content).bottom<=bounds(findWithin(find("Start profile and power"),"Power")).top,"Power popover opens above its button");check(findWithin(content,"Restart Nth Desktop")!=null&&findWithin(content,"Android power settings")!=null,"Power actions use real Android and launcher destinations");});if(!landscape&&alignment.equals("Left"))shotPopup("eleven-screenshot-power");sendKeyDownUpSync(KeyEvent.KEYCODE_ESCAPE);settle();ui(()->home.onBackPressed());
  }
  ui(()->home.open("start-menu:"));settle();ui(()->find("Start profile").performClick());settle();ui(()->{StartMenu menu=TenSmoke.find(root,StartMenu.class);DesktopContextMenu popup=(DesktopContextMenu)field(menu,"footerMenu");check(findWithin((View)field(popup,"items"),"Account settings")!=null,"Start profile opens account options");popup.dismiss();home.onBackPressed();});
  ui(()->invokeDesktop());settle();ui(()->{DesktopContextMenu modern=(DesktopContextMenu)field(home,"desktopMenu");View more=findWithin((View)field(modern,"items"),"Show more options");check(more!=null,"Modern desktop includes Show more options");more.performClick();check(!modern.showing(),"Classic menu replaces the modern menu");});settle();
  ui(()->{DesktopContextMenu classic=(DesktopContextMenu)field(home,"desktopMenu");View items=(View)field(classic,"items");for(String label:new String[]{"View","Sort by","Refresh","Paste","Open in Terminal","New","Display settings","Personalize"})check(findWithin(items,label)!=null,"Classic desktop command: "+label);check(findWithin(items,"Desktop tools")==null&&findWithin(items,"Desktop background")==null,"Classic menu follows the recorded command list");});shotPopup("eleven-screenshot-classic-menu");sendKeyDownUpSync(KeyEvent.KEYCODE_ESCAPE);settle();
  ui(()->{store.prefs.edit().putString("ten_search_mode","Hidden").commit();home.applyTenAppearance();});settle();check(find("Search")==null,"Explicit Hidden Search choice remains honored");
  ui(()->{android.graphics.drawable.Drawable icon=home.getApplicationInfo().loadIcon(home.getPackageManager());Bitmap bitmap=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,192,192);icon.draw(new Canvas(bitmap));check(icon instanceof android.graphics.drawable.AdaptiveIconDrawable,"Android loads the actual adaptive icon");int white=whitePixels(bitmap);save(bitmap,"eleven-screenshot-app-icon");Bitmap circle=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(circle);Path mask=new Path();mask.addCircle(96,96,96,Path.Direction.CW);canvas.clipPath(mask);icon.draw(canvas);check(whitePixels(circle)==white,"Circular Android mask preserves every white glyph pixel");save(circle,"eleven-screenshot-app-icon-circle");});
  out.putString("stream","PASS: Eleven owner screenshot fixes "+checks+" assertions; portrait/landscape, Left/Center, native Search tap/results, upper row origin, initial label clearance, full-width Start footer, persistent Power, account options, replacing classic menu, mask-safe application icon and explicit Search visibility.\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
 void invokeDesktop(){try{Method method=MainActivity.class.getDeclaredMethod("desktopOptions",float.class,float.class);method.setAccessible(true);method.invoke(home,root.getWidth()/2f,root.getHeight()/2f);}catch(Exception e){throw new RuntimeException(e);}}
 Object field(Object object,String name){try{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception e){throw new RuntimeException(e);}}
 View find(String name){return TenSmoke.description(root,name);}
 View findWithin(View view,String name){if(name.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||view instanceof TextView&&name.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=findWithin(((ViewGroup)view).getChildAt(i),name);if(found!=null)return found;}return null;}
 Rect bounds(View view){int[] at=new int[2];view.getLocationOnScreen(at);return new Rect(at[0],at[1],at[0]+view.getWidth(),at[1]+view.getHeight());}
 void tap(View view)throws Exception{Rect box=bounds(view);long now=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,box.centerX(),box.centerY(),0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Native touch injected");event.recycle();}}
 void settle()throws Exception{waitForIdleSync();Thread.sleep(250);waitForIdleSync();}
 void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(25,TimeUnit.SECONDS);}
 void check(boolean good,String message){checks++;if(!good)throw new AssertionError(message);}
 int whitePixels(Bitmap bitmap){int count=0;for(int y=0;y<bitmap.getHeight();y++)for(int x=0;x<bitmap.getWidth();x++){int c=bitmap.getPixel(x,y);if(Color.alpha(c)>200&&Color.red(c)>235&&Color.green(c)>235&&Color.blue(c)>235)count++;}return count;}
 void save(Bitmap bitmap,String name){try(OutputStream file=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,file);}catch(IOException e){throw new RuntimeException(e);}finally{bitmap.recycle();}}
 void shot(String name)throws Exception{ui(()->{Bitmap bitmap=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap));save(bitmap,name);});}
 void shotPopup(String name)throws Exception{ui(()->{DesktopContextMenu menu=(DesktopContextMenu)field(home,"desktopMenu");StartMenu start=TenSmoke.find(root,StartMenu.class);if(start!=null&&start.getVisibility()==View.VISIBLE)menu=(DesktopContextMenu)field(start,"footerMenu");View content=(View)((View)field(menu,"items")).getParent();Bitmap bitmap=Bitmap.createBitmap(content.getWidth(),content.getHeight(),Bitmap.Config.ARGB_8888);content.draw(new Canvas(bitmap));save(bitmap,name);});}
}
